"""Recognising which motion library a project uses (pytmc.motion_library)."""
import re

import pytest

from pytmc import motion_library, parser

from . import conftest
from .conftest import make_mock_type

SAMPLE = "motion_abstraction_sample.tmc"
LEGACY = "tc_mot_example.tmc"


@pytest.mark.parametrize(
    "namespace",
    [
        "LCLS_Tc_Motion",
        "lcls_tc_motion",
        "LCLS_MotionAbstraction",
        "LCLS_OOPMotion",
    ],
)
def test_new_library_namespaces(namespace):
    assert motion_library.is_new_library_type(
        make_mock_type("ST_PositionState", namespace=namespace)
    )


@pytest.mark.parametrize("namespace", ["lcls_twincat_motion", "SomethingElse", None])
def test_other_namespaces_are_not_the_new_library(namespace):
    assert not motion_library.is_new_library_type(
        make_mock_type("ST_PositionState", namespace=namespace)
    )


def test_a_type_name_alone_is_not_a_namespace():
    # a type called like the namespace, but with no namespace of its own
    assert not motion_library.is_new_library_type(make_mock_type("LCLS_Tc_Motion"))
    assert not motion_library.is_new_library_type(object())


def test_state_types_in_test_tmcs():
    """The namespace on real data types tells the libraries apart."""
    for name, is_new in ((SAMPLE, True), (LEGACY, False)):
        tmc = parser.parse(conftest.TMC_ROOT / name)
        state_symbols = [
            sym
            for sym in tmc.find(parser.Symbol)
            if sym.data_type.name == "ST_PositionState"
        ]
        assert state_symbols, name
        for sym in state_symbols:
            assert motion_library.is_new_library_symbol(sym) is is_new, (
                name,
                sym.data_type.qualified_type_name,
            )


def test_nc_mapped_motor_symbols():
    """An FB_MotionStage is new-library once it has an axis-link, however it is typed."""
    tmc = parser.parse(conftest.TMC_ROOT / SAMPLE)
    stages = list(tmc.find(parser.Symbol_FB_MotionStage))
    assert stages
    assert all(motion_library.is_new_library_symbol(stage) for stage in stages)

    legacy = parser.parse(conftest.TMC_ROOT / LEGACY)
    stages = list(legacy.find(parser.Symbol_FB_MotionStage))
    assert stages  # FB_MotionStage exists in the legacy library too
    assert not any(motion_library.is_new_library_symbol(stage) for stage in stages)


def test_motor_predicates():
    tmc = parser.parse(conftest.TMC_ROOT / SAMPLE)
    stages = list(tmc.find(parser.Symbol_FB_MotionStage))
    assert any(motion_library.is_nc_mapped_motor(stage) for stage in stages)
    assert not any(motion_library.is_legacy_motor(stage) for stage in stages)

    legacy = parser.parse(conftest.TMC_ROOT / LEGACY)
    st_motors = list(legacy.find(parser.Symbol_ST_MotionStage))
    assert st_motors
    assert all(
        motion_library.is_legacy_motor(mot) != mot.is_pointer for mot in st_motors
    )
    assert not any(motion_library.is_nc_mapped_motor(mot) for mot in st_motors)


@pytest.mark.parametrize(
    "name, expected",
    [
        (SAMPLE, True),
        (LEGACY, False),
        ("ArbiterPLC.tmc", False),
        ("xtes_sxr_plc.tmc", False),
    ],
)
def test_uses_new_library_on_test_tmcs(name, expected):
    tmc = parser.parse(conftest.TMC_ROOT / name)
    assert motion_library.uses_new_library(tmc) is expected


def _sample_edited(tmp_path, *, rename_namespace=False, drop_axis_link=False):
    src = (conftest.TMC_ROOT / SAMPLE).read_text(encoding="utf-8")
    if rename_namespace:
        src = src.replace("LCLS_Tc_Motion", "lcls_twincat_motion")
    if drop_axis_link:
        src = re.sub(r"axis-link:[^\n<]*", "", src)
    path = tmp_path / "edited.tmc"
    path.write_text(src, encoding="utf-8")
    return parser.parse(path)


@pytest.mark.parametrize(
    "rename_namespace, drop_axis_link, expected",
    [
        pytest.param(False, False, True, id="both-signals"),
        pytest.param(False, True, True, id="namespace-only"),
        pytest.param(True, False, True, id="axis-link-only"),
        pytest.param(True, True, False, id="neither"),
    ],
)
def test_either_signal_is_enough(tmp_path, rename_namespace, drop_axis_link, expected):
    tmc = _sample_edited(
        tmp_path, rename_namespace=rename_namespace, drop_axis_link=drop_axis_link
    )
    assert motion_library.uses_new_library(tmc) is expected
